const formatLabels: Record<ArticleFormat, string> = {
  "field-guide": "FIELD GUIDE",
  explainer: "EXPLAINER",
  "research-brief": "RESEARCH BRIEF",
  "video-recap": "VIDEO DEBRIEF",
  "policy-analysis": "POLICY LENS",
  "operator-playbook": "OPERATOR PLAYBOOK",
};

const formatIntros: Record<ArticleFormat, string> = {
  "field-guide": "The useful way into this subject is a sequence of decisions, not a pile of terminology.",
  explainer: "The concept sounds abstract until it is separated into inputs, mechanism, output and evidence.",
  "research-brief": "The research signal deserves attention, but the headline becomes useful only after its evidence and limits are kept together.",
  "video-recap": "The official video is a demonstration of a product or research direction, not an independent evaluation. This debrief treats it as primary-source evidence and tests the claims against practical constraints.",
  "policy-analysis": "Policy language matters most when it changes a concrete duty, decision or route to recourse.",
  "operator-playbook": "The goal is a repeatable operating practice that produces evidence, not a one-time burst of AI activity.",
};

const accentByCategory: Record<Article["category"], string> = {
  Canada: "#596874",
  Models: "#49556a",
  Products: "#6a6259",
  Business: "#53645e",
  Research: "#5c5870",
  Policy: "#68615a",
};

function publicationDate(index: number) {
  const date = new Date(Date.UTC(2026, 7, 10));
  date.setUTCDate(date.getUTCDate() - index);
  return {
    date: date.toISOString().slice(0, 10),
    displayDate: new Intl.DateTimeFormat("en-CA", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }).format(date),
  };
}

function secondWavePublicationDate() {
  const date = new Date(Date.UTC(2026, 7, 17));
  return {
    date: date.toISOString().slice(0, 10),
    displayDate: new Intl.DateTimeFormat("en-CA", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }).format(date),
  };
}

function buildSections(seed: ExpansionSeed) {
  const intro = formatIntros[seed.format];
  const videoParagraph = seed.videoKey
    ? `The embedded video is included so readers can inspect the demonstration directly. We summarize its central idea rather than reproduce its script, and we keep vendor claims separate from our analysis. Watch for what the camera shows, what the presenter says, and what evidence is not available in the edited sequence. A useful viewing habit is to pause after each major capability and ask what data, integration, human review and failure recovery would be necessary outside the demonstration.`
    : `The strongest reading combines the named primary sources rather than relying on a single announcement. One source defines the capability or policy, another supplies a risk or implementation lens, and the article's analysis connects them to a realistic decision. That triangulation cannot remove uncertainty, but it makes assumptions easier to see and update.`;

  return [
    {
      heading: `The signal: ${seed.subject}`,
      paragraphs: [
        `${intro} ${seed.thesis} That distinction is the centre of this article. It tells us what deserves attention, what can be tested now, and which claims should remain provisional. AI coverage often collapses a system into the name of a model or a dramatic demonstration. In practice, outcomes emerge from people, data, interfaces, incentives and operating conditions as much as from a set of weights.`,
        `${seed.evidence} This is credible primary-source evidence about direction, design or stated results. It is not universal proof. The responsible move is to translate the claim into observable questions and compare it with the setting in which a reader might act. Throughout this guide, factual descriptions stay connected to the source list, while recommendations are clearly presented as analysis.`
      ],
    },
    {
      heading: seed.format === "video-recap" ? "What the official video demonstrates" : "What the primary evidence establishes",
      paragraphs: [
        videoParagraph,
        `The evidence supports a focused conclusion: ${seed.evidence} It does not establish that every user, organization or region will see the same outcome. Product versions, access rules, prices, laws and local conditions change. Readers should use the publication date and linked sources to check time-sensitive details before making a consequential choice.`
      ],
      bullets: [
        `Supported signal: ${seed.thesis}`,
        `Evidence boundary: ${seed.constraint}`,
        `Reader task: separate demonstrated capability from dependable performance in your own context.`,
      ],
    },
    {
      heading: "How the system works",
      paragraphs: [
        `${seed.mechanism} Thinking in components is more than a technical exercise. It shows where evidence can be collected and where control can be added. Inputs can be checked for authority and permission; retrieval can be tested for coverage; generated output can be validated; tools can be constrained; and a human decision can be documented.`,
        `A useful system map follows one item from beginning to end. Identify who supplies it, what transformation occurs, which model or service is involved, what gets stored, who sees the result and what happens next. Then mark every point where a wrong or delayed result could change the outcome. This prevents an impressive interface from hiding a fragile process and gives non-technical reviewers a concrete way to participate.`
      ],
    },
    {
      heading: "Where the value can be real",
      paragraphs: [
        `${seed.practice} This is deliberately narrower than a promise to transform everything. A bounded use case has a recognizable starting state, a responsible owner and a result that can be compared. It also creates a place for workers and affected users to describe quality in terms that matter to them rather than accepting a vendor's benchmark as the only definition.`,
        `Value should be counted after the whole workflow settles. Include time spent preparing data, reviewing output, correcting errors, handling exceptions, integrating systems and supporting users. Also count changes in cycle time, accessibility, consistency, capacity and risk. A tool may be worthwhile even when it does not reduce headcount; it may let a small team provide a service that was previously delayed or unavailable. The claim should match the measured benefit.`
      ],
      bullets: seed.actions,
    },
    {
      heading: "Limits and failure modes",
      paragraphs: [
        `${seed.constraint} This is not a footnote. It defines the conditions under which the article's recommendation should change. Every AI system has an operating envelope: the tasks, users, data and environments for which evidence exists. Problems begin when a successful example is silently extended beyond that envelope.`,
        `Failure is rarely one dramatic event. More often it appears as small unsupported claims, uneven quality across groups, stale information, review fatigue, rising cost or a workaround that becomes permanent. Track those signals before they become normal. Preserve representative errors, investigate causes across the complete system and change the workflow instead of repeatedly asking users to be more careful around a bad design.`
      ],
    },
    {
      heading: "A practical playbook",
      paragraphs: [
        `Begin by writing the intended outcome in one sentence and naming the person accountable for it. Record the current baseline, select representative examples and define errors that are unacceptable even if average quality is high. Keep the first version reversible. Limit data, permissions, users and duration, and make the fallback path usable rather than ceremonial.`,
        `Run the test long enough to encounter ordinary pressure: busy periods, ambiguous inputs, absent staff and source changes. Review results with the people who perform the work and people affected by it. Decide to scale, revise or stop against criteria written before the result was known. If the system advances, keep the evaluation suite, incident route and ownership structure with it.`
      ],
      bullets: [
        seed.actions[0],
        seed.actions[1],
        seed.actions[2],
        "Record the model, prompt, source and policy versions used in the decision.",
        "Schedule a review date instead of assuming the first approval remains valid forever.",
      ],
    },
    {
      heading: "A worked decision frame",
      paragraphs: [
        `Imagine a team deciding what to do about ${seed.subject}. One group sees a reason to move quickly; another sees reasons to wait. Instead of voting from impressions, turn the disagreement into a written decision: the proposed use, the people affected, the expected benefit, the evidence available now and the result that would make the team reverse course. Then connect that decision to the article's central finding: ${seed.thesis}`,
        `Stress-test the proposal with the most important boundary: ${seed.constraint} Ask the team to show how ${seed.practice.toLowerCase()} would operate on an ordinary day and during a difficult edge case. A credible plan should reveal its data, review load, fallback, incident owner and exit path. If those elements cannot be demonstrated at pilot scale, increasing model capability or purchasing a broader licence will not repair the missing operating design.`
      ],
    },
    {
      heading: "Questions worth asking before you act",
      paragraphs: [
        `Good questions slow down the part of a project that is cheap to change and speed up the part that would otherwise fail in production. They also distribute expertise: a lawyer, operator, researcher, worker or user may see a different weak point in the same workflow. The following questions are intentionally concrete enough to require evidence rather than reassurance.`,
        `Do not accept "the model is accurate" or "a human is in the loop" as complete answers. Ask for the task definition, test population, error distribution, reviewer authority, data flow, model version and recovery path. If the team cannot produce that information, the gap is itself a finding and should narrow the deployment until evidence exists.`
      ],
      bullets: seed.questions,
    },
    {
      heading: "What to watch next",
      paragraphs: [
        `The next useful signals are ${seed.watch}. Each can be observed without predicting a distant artificial-general-intelligence milestone. They show whether capability is becoming dependable infrastructure, whether safeguards operate under pressure and whether benefits reach the people named in the announcement.`,
        `Update your view when the evidence changes. Product names and benchmark leaders will move quickly; the more durable questions concern authority, measurement, reversibility and who carries the downside of error. Bookmark the primary sources below, compare new announcements with this article's decision framework and prefer documented outcomes over confident forecasts.`
      ],
    },
    {
      heading: "The bottom line",
      paragraphs: [
        `${seed.thesis} The practical consequence is equally clear: ${seed.practice} That combination of ambition and verification is the most useful way to engage with fast-moving AI. It leaves room for genuine advances without treating uncertainty as a reason for either hype or paralysis.`,
        `Use this article as a working brief. Take the action list into a project meeting, replace assumptions with local evidence and record what would make the decision change. When the underlying source, model or policy is updated, revisit the relevant section rather than carrying an old conclusion forward. High-quality AI practice is not certainty; it is a disciplined ability to learn and correct course.`
      ],
    },
  ];
}

const heldForLater = new Set([
  "canadian-ai-copyright-creator-checklist",
  "canada-ai-job-transition-local-playbook",
  "confidence-calibration-ai-systems",
  "mixture-of-experts-models-explained",
  "synthetic-data-ai-training-guide",
  "ai-job-search-honest-workflow",
  "ai-travel-planning-verification-guide",
  "ai-sales-research-source-backed",
  "ai-personal-automation-permission-ladder",
  "ai-neuroscience-brain-data",
]);

const firstWaveSeeds = expansionSeeds.filter((seed) => !heldForLater.has(seed.slug));
const preparedSecondWaveSeeds = expansionSeeds.filter((seed) => heldForLater.has(seed.slug));
const publishedExpansionSeeds = SITE_FEATURES.secondWaveGuides
  ? [...firstWaveSeeds, ...preparedSecondWaveSeeds]
  : firstWaveSeeds;
const seedTitles = new Map(expansionSeeds.map((seed) => [seed.slug, seed.title]));

export const expansionArticles: Article[] = publishedExpansionSeeds.map((seed, index) => {
  const published = heldForLater.has(seed.slug) ? secondWavePublicationDate() : publicationDate(index);
  const sources = seed.sourceKeys.map((key) => sourceLibrary[key]);
  return {
    slug: seed.slug,
    title: seed.title,
    dek: seed.dek,
    category: seed.category,
    date: published.date,
    displayDate: published.displayDate,
    readTime: "12 min read",
    signal: formatLabels[seed.format],
    accent: accentByCategory[seed.category],
    sourceLabel: sources[0].label,
    sourceUrl: sources[0].url,
    sources,
    internalLinks: seed.relatedSlugs?.map((slug) => ({ slug, title: seedTitles.get(slug) ?? slug })),
    image: `/images/articles/unique/${seed.slug}.jpg`,
    imageAlt: seed.imageAlt ?? seed.visualPrompt,
    disclaimer: seed.format === "video-recap"
      ? "This independent analysis summarizes an official product or research video and adds original context, limitations and a practical evaluation framework. It is not a transcript, endorsement or substitute for watching the source."
      : "This evidence-led explainer uses the linked primary sources and original AI New analysis. It is educational, not legal, medical, financial or procurement advice; verify current requirements with qualified professionals.",
    evidenceStatus: "verified",
    searchEligible: true,
    sections: buildSections(seed),
    video: seed.videoKey ? videoLibrary[seed.videoKey] : undefined,
  };
});

export const expansionImagePrompts = publishedExpansionSeeds.map(({ slug, title, visualPrompt }, index) => ({
  slug,
  title,
  styleIndex: index % 12,
  prompt: visualPrompt,
}));

export const preparedSecondWaveImagePrompts = preparedSecondWaveSeeds.map(({ slug, title, visualPrompt }, index) => ({
  slug,
  title,
  styleIndex: index,
  prompt: visualPrompt,
}));
